/**
 * Render one glyph as inline SVG with a currentColor fill.
 *
 * @param string $slug Registry slug.
 * @param int    $size Pixel size for width and height.
 * @return string SVG markup, or '' for an unknown slug.
 */
function murtadd_social_icon( $slug, $size = 20 ) {
	$reg = murtadd_social_registry();
	if ( ! isset( $reg[ $slug ] ) ) {
		return '';
	}
	$inner = 'path' === $reg[ $slug ]['kind']
		? '<path d="' . $reg[ $slug ]['svg'] . '"/>'
		: $reg[ $slug ]['svg'];
	return sprintf(
		'<svg viewBox="0 0 24 24" width="%1$d" height="%1$d" aria-hidden="true" focusable="false" fill="currentColor">%2$s</svg>',
		(int) $size,
		$inner
	);
}

/**
 * Saved profile URLs, slug => url, in registry order, non-empty only.
 *
 * @return array<string,string>
 */
function murtadd_social_profiles() {
	$saved = get_option( 'murtadd_profiles', array() );
	$saved = is_array( $saved ) ? $saved : array();
	$out   = array();
	foreach ( murtadd_social_registry() as $slug => $meta ) {
		if ( ! empty( $saved[ $slug ] ) ) {
			$out[ $slug ] = $saved[ $slug ];
		}
	}
	return $out;
}
